notifyDef:
CREATE OR REPLACE FUNCTION public.bfr_pf_notify_location()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_key text;
  v_ids jsonb;
begin
  select s.decrypted_secret into v_key
    from vault.decrypted_secrets s
   where s.name = 'pf_emissor_service_role'
   limit 1;

  if v_key is null then
    raise warning 'bfr_pf_notify_location: segredo pf_emissor_service_role ausente';
    return new;
  end if;

  select jsonb_agg(sh.profile_id order by sh.profile_id)
    into v_ids
    from public.student_location_sharing sh
   where sh.student_id = new.student_id
     and sh.enabled
     and sh.profile_id is distinct from new.reported_by_profile_id;

  if v_ids is null then
    return new;
  end if;

  perform net.http_post(
    url := 'https://yyzqoxlkcvqpessypfjo.supabase.co/functions/v1/send-school-notification',
    body := jsonb_build_object(
      'title', 'Atualização de localização',
      'body', 'Uma nova localização foi compartilhada. Abra o BFR Conecta para ver no mapa.',
      'profile_ids', v_ids
    ),
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_key,
      'apikey', v_key
    ),
    timeout_milliseconds := 5000
  );

  return new;
exception
  when others then
    raise warning 'bfr_pf_notify_location: falha ao enfileirar (%)', sqlerrm;
    return new;
end;
$function$

reportDef:
CREATE OR REPLACE FUNCTION public.bfr_report_location(p_student_id uuid, p_lat double precision, p_lon double precision, p_acc double precision DEFAULT NULL::double precision)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller uuid := auth.uid();
  v_source text;
  v_throttled boolean;
begin
  if v_caller is null then
    raise exception 'nao autenticado' using errcode = '42501';
  end if;
  if p_lat < -90 or p_lat > 90 or p_lon < -180 or p_lon > 180 then
    raise exception 'coordenadas invalidas' using errcode = '22023';
  end if;
  if exists (select 1 from public.guardian_students where profile_id = v_caller and student_id = p_student_id) then
    v_source := 'guardian_app';
    if not exists (select 1 from public.student_location_sharing
                   where profile_id = v_caller and student_id = p_student_id and enabled) then
      raise exception 'compartilhamento desativado' using errcode = '42501';
    end if;
  elsif exists (select 1 from public.students where id = p_student_id and student_profile_id = v_caller) then
    v_source := 'student_app';
    if not exists (select 1 from public.student_location_sharing where student_id = p_student_id and enabled) then
      raise exception 'compartilhamento desativado' using errcode = '42501';
    end if;
  else
    raise exception 'sem vinculo com o aluno' using errcode = '42501';
  end if;
  insert into public.student_location_report_throttle (profile_id, student_id, last_report_at)
  values (v_caller, p_student_id, now())
  on conflict (profile_id, student_id) do update
    set last_report_at = excluded.last_report_at
    where public.student_location_report_throttle.last_report_at <= now() - interval '30 seconds'
  returning true into v_throttled;
  if v_throttled is null then
    raise exception 'rate_limit: aguarde 30 segundos' using errcode = 'P0001';
  end if;
  insert into public.student_locations
    (student_id, latitude, longitude, accuracy_m, reported_by_profile_id, source, reported_at)
  values (p_student_id, p_lat, p_lon, p_acc, v_caller, v_source, now())
  on conflict (student_id) do update
    set latitude = excluded.latitude, longitude = excluded.longitude,
        accuracy_m = excluded.accuracy_m, reported_by_profile_id = excluded.reported_by_profile_id,
        source = excluded.source, reported_at = excluded.reported_at;
  return jsonb_build_object('ok', true, 'source', v_source, 'reported_at', now());
end;
$function$
